-- Player Stats identity/history repair. Run THIS WHOLE FILE in one SQL Editor run.
-- The executable migration is deliberately ONE anonymous SQL statement so the
-- Supabase SQL Editor cannot lose setup objects between separately run statements.
-- Safe to run again. No reset, DELETE, TRUNCATE, player merge, ID rewrite,
-- reactivation or deactivation. No competition/prediction/card/result/stat writes.
-- Existing historical rows and every existing foreign key are preserved.
--
-- Repairs only evidence-backed cases:
-- 1. Add documented registered/former names for search, sourced from the existing
--    player-identity-nationality-update-2025-26.sql NAME mapping (not its updates).
-- 2. Copy an exact current-season assignment from an unused inactive identity to
--    the sole active identity, only for the SAME current club and no target history.
--    Leave the original identity/assignment intact. Never infer transfer dates.
-- 3. Restore single-Gameweek assignment evidence from existing fixture stats,
--    only if the recorded club really played the fixture and no history conflicts.
-- 4. Fill a NULL current team only from a unique open assignment covering current GW.
-- Non-null mismatches, conflicting identities, uncertain tenure and inactive-only
-- identities are reported, not guessed. Review audit output before/after running.

do $player_stats_migration$
declare
  player_stats_integrity_report jsonb;
begin
set local lock_timeout = '5s';
set local statement_timeout = '90s';
perform pg_advisory_xact_lock(hashtext('pp_player_stats_pool_integrity_20260828'));

-- Supabase's SQL Editor may commit individual top-level statements. Temporary
-- objects and migration-owned schemas have both proved unreliable there. Use
-- uniquely named persistent staging tables in public instead. They are revoked
-- immediately, cleaned before a retry, and removed after a successful run.
drop schema if exists pp_migration_player_stats_20260829 cascade;
drop table if exists
  public.pp_migration_player_stats_20260829_unique_active,
  public.pp_migration_player_stats_20260829_identity_matches,
  public.pp_migration_player_stats_20260829_identity_source,
  public.pp_migration_player_stats_20260829_repairs,
  public.pp_migration_player_stats_20260829_season
cascade;

create schema if not exists extensions;
create extension if not exists unaccent with schema extensions;

create or replace function public.pp_player_identity_key(value text)
returns text language sql stable
set search_path = pg_catalog, public, extensions
as $$ select regexp_replace(lower(unaccent(coalesce(value, ''))), '[^a-z0-9]', '', 'g'); $$;

create or replace function public.pp_player_country_key(value text)
returns text language sql stable
set search_path = pg_catalog, public
as $$
  select case public.pp_player_identity_key(value)
    when 'republicofireland' then 'ireland'
    when 'cotedivoire' then 'ivorycoast'
    when 'unitedstatesofamerica' then 'unitedstates'
    when 'usa' then 'unitedstates'
    when 'turkiye' then 'turkey'
    when 'czechia' then 'czechrepublic'
    when 'drcongo' then 'democraticrepublicofthecongo'
    else public.pp_player_identity_key(value) end;
$$;

create table if not exists public.player_name_aliases (
  player_id uuid not null references public.players(id) on delete cascade,
  name text not null check (btrim(name) <> ''),
  source_key text not null,
  primary key (player_id, name)
);
alter table public.player_name_aliases enable row level security;
if not exists (select 1 from pg_policies where schemaname = 'public'
    and tablename = 'player_name_aliases' and policyname = 'authenticated read player names') then
  create policy "authenticated read player names" on public.player_name_aliases
    for select to authenticated using (true);
end if;
if not exists (select 1 from pg_policies where schemaname = 'public'
    and tablename = 'player_name_aliases' and policyname = 'admins manage player names') then
  create policy "admins manage player names" on public.player_name_aliases
    for all to authenticated using (public.is_admin()) with check (public.is_admin());
end if;
grant select, insert, update, delete on public.player_name_aliases to authenticated;

create table public.pp_migration_player_stats_20260829_season as
select s.id, s.name, coalesce((
  select min(g.number) from public.gameweeks g
  where g.season_id = s.id and exists (
    select 1 from public.fixtures f where f.season_id = s.id
      and f.gameweek_id = g.id and f.status not in ('final', 'postponed')
  )
), (select max(g.number) from public.gameweeks g where g.season_id = s.id)) as current_gw
from public.seasons s where s.is_active = true;
revoke all on public.pp_migration_player_stats_20260829_season from public, anon, authenticated;
if (select count(*) from public.pp_migration_player_stats_20260829_season) <> 1 then
  raise exception 'Stopped safely: exactly one active season is required. No changes committed.';
end if;

create table public.pp_migration_player_stats_20260829_repairs (
  repair text, player_id uuid, display_name text, details jsonb
);
revoke all on public.pp_migration_player_stats_20260829_repairs from public, anon, authenticated;

create table public.pp_migration_player_stats_20260829_identity_source (
  source_key text primary key, nationality text, canonical_name text not null, names text[] not null
);
revoke all on public.pp_migration_player_stats_20260829_identity_source from public, anon, authenticated;

-- BEGIN GENERATED NAME EVIDENCE (no clubs, activation or roster facts imported).
-- END GENERATED NAME EVIDENCE

create table public.pp_migration_player_stats_20260829_identity_matches as
with names as materialized (
  select distinct s.source_key, public.pp_player_country_key(s.nationality) as country_key,
    public.pp_player_identity_key(n) as name_key
  from public.pp_migration_player_stats_20260829_identity_source s cross join lateral unnest(s.names) n
), identities as materialized (
  select p.id, public.pp_player_country_key(p.nationality) as country_key,
    public.pp_player_identity_key(p.display_name) as name_key from public.players p
), candidates as (
  select distinct p.id as player_id, s.source_key
  from names s join identities p on p.name_key = s.name_key and p.country_key = s.country_key
)
select player_id, min(source_key) as source_key
from candidates group by player_id having count(*) = 1;
revoke all on public.pp_migration_player_stats_20260829_identity_matches from public, anon, authenticated;

with added as (
  select distinct m.player_id, n, m.source_key
  from public.pp_migration_player_stats_20260829_identity_matches m
  join public.pp_migration_player_stats_20260829_identity_source s using (source_key)
  cross join lateral unnest(s.names) n
  where btrim(n) <> ''
  on conflict (player_id, name) do nothing
  returning player_id
)
select 'search_names_added', p.id, p.display_name, jsonb_build_object('names_added', count(*))
from added a join public.players p on p.id = a.player_id group by p.id, p.display_name;

-- A single active row identifies the canonical candidate; more than one is ambiguous.
create table public.pp_migration_player_stats_20260829_unique_active as
select m.source_key, (array_agg(p.id) filter (where p.is_active))[1] as player_id
from public.pp_migration_player_stats_20260829_identity_matches m join public.players p on p.id = m.player_id
group by m.source_key having count(*) filter (where p.is_active) = 1;
revoke all on public.pp_migration_player_stats_20260829_unique_active from public, anon, authenticated;

with evidence as (
  select distinct c.id as player_id, c.display_name, a.season_id, a.team_id,
    a.starts_gameweek_id, a.ends_gameweek_id
  from public.pp_migration_player_stats_20260829_unique_active u
  join public.players c on c.id = u.player_id
  join public.pp_migration_player_stats_20260829_identity_source source on source.source_key = u.source_key
  join public.pp_migration_player_stats_20260829_identity_matches m on m.source_key = u.source_key and m.player_id <> c.id
  join public.players old on old.id = m.player_id and old.is_active = false
  join public.player_team_assignments a on a.player_id = old.id
  join public.pp_migration_player_stats_20260829_season s on s.id = a.season_id
  join public.gameweeks start_gw on start_gw.id = a.starts_gameweek_id and start_gw.season_id = s.id
  left join public.gameweeks end_gw on end_gw.id = a.ends_gameweek_id and end_gw.season_id = s.id
  where old.team_id = c.team_id and a.team_id = c.team_id
    and public.pp_player_identity_key(c.display_name) = public.pp_player_identity_key(source.canonical_name)
    and (a.ends_gameweek_id is null or end_gw.number >= start_gw.number)
    and exists (select 1 from public.fixtures f where f.season_id = s.id
      and a.team_id in (f.home_team_id, f.away_team_id))
    and not exists (select 1 from public.player_team_assignments x
      where x.player_id = c.id and x.season_id = s.id)
    -- Do not hide a transfer, an overlapping club, or history on another identity.
    and not exists (select 1 from public.pp_migration_player_stats_20260829_identity_matches peers
      join public.player_team_assignments x on x.player_id = peers.player_id
      where peers.source_key = u.source_key and x.season_id = s.id and x.team_id <> c.team_id)
    and not exists (select 1 from public.pp_migration_player_stats_20260829_identity_matches peers
      join public.player_fixture_stats x on x.player_id = peers.player_id
      where peers.source_key = u.source_key and peers.player_id <> c.id and x.season_id = s.id)
    and not exists (select 1 from public.pp_migration_player_stats_20260829_identity_matches peers
      join public.player_gameweek_stats x on x.player_id = peers.player_id
      where peers.source_key = u.source_key and peers.player_id <> c.id and x.season_id = s.id)
    and not exists (select 1 from public.pp_migration_player_stats_20260829_identity_matches peers
      join public.star_man_picks x on x.player_id = peers.player_id
      where peers.source_key = u.source_key and peers.player_id <> c.id and x.season_id = s.id)
), added as (
  select season_id, player_id, team_id, starts_gameweek_id, ends_gameweek_id from evidence
  returning *
)
select 'assignment_copied_from_unused_identity', p.id, p.display_name,
  jsonb_build_object('team_id', a.team_id, 'from_gw_id', a.starts_gameweek_id, 'to_gw_id', a.ends_gameweek_id)
from added a join public.players p on p.id = a.player_id;

-- Fixture stats provide evidence for that single GW, never an invented full season.
with evidence as (
  select x.season_id, x.player_id, x.gameweek_id,
    (array_agg(distinct x.team_id))[1] as team_id
  from public.player_fixture_stats x
  join public.pp_migration_player_stats_20260829_season s on s.id = x.season_id
  join public.fixtures f on f.id = x.fixture_id and f.season_id = x.season_id
    and f.gameweek_id = x.gameweek_id and x.team_id in (f.home_team_id, f.away_team_id)
  group by x.season_id, x.player_id, x.gameweek_id
  having count(distinct x.team_id) = 1
), added as (
  select e.season_id, e.player_id, e.team_id, e.gameweek_id, e.gameweek_id
  from evidence e join public.gameweeks gw on gw.id = e.gameweek_id and gw.season_id = e.season_id
  where not exists (
    select 1 from public.player_team_assignments a
    join public.gameweeks start_gw on start_gw.id = a.starts_gameweek_id and start_gw.season_id = a.season_id
    left join public.gameweeks end_gw on end_gw.id = a.ends_gameweek_id and end_gw.season_id = a.season_id
    where a.player_id = e.player_id and a.season_id = e.season_id
      and start_gw.number <= gw.number and (a.ends_gameweek_id is null or end_gw.number >= gw.number)
  )
  returning *
)
select 'single_gw_history_from_fixture_stats', p.id, p.display_name,
  jsonb_build_object('team_id', a.team_id, 'gameweek_id', a.starts_gameweek_id)
from added a join public.players p on p.id = a.player_id;

with evidence as (
  select a.player_id, (array_agg(distinct a.team_id))[1] as team_id
  from public.player_team_assignments a join public.pp_migration_player_stats_20260829_season s on s.id = a.season_id
  join public.gameweeks start_gw on start_gw.id = a.starts_gameweek_id and start_gw.season_id = s.id
  left join public.gameweeks end_gw on end_gw.id = a.ends_gameweek_id and end_gw.season_id = s.id
  where start_gw.number <= s.current_gw and (a.ends_gameweek_id is null or end_gw.number >= s.current_gw)
  group by a.player_id having count(distinct a.team_id) = 1 and bool_and(a.ends_gameweek_id is null)
), repaired as (
  update public.players p set team_id = e.team_id
  from evidence e
  where p.id = e.player_id and p.is_active = true and p.team_id is null
    and exists (select 1 from public.fixtures f join public.pp_migration_player_stats_20260829_season s on s.id = f.season_id
      where e.team_id in (f.home_team_id, f.away_team_id))
    and not exists (select 1 from public.players other where other.id <> p.id
      and other.team_id = e.team_id and other.display_name = p.display_name)
  returning p.id, p.display_name, p.team_id
)
select 'null_current_team_from_open_history', id, display_name, jsonb_build_object('team_id', team_id) from repaired;

-- Reusable READ-ONLY report. Includes informational intentional deactivations;
-- do not reactivate them just because they appear here. API-cap finding assumes
-- the default 1,000-row Supabase setting; adjust argument if configured otherwise.
create or replace function public.audit_player_stats_pool(api_row_cap integer default 1000)
returns table (issue text, player_id uuid, display_name text, details jsonb)
language sql stable
set search_path = pg_catalog, public
as $$
with season as (select id from public.seasons where is_active),
ranked as (select p.*, row_number() over (order by display_name, id) as api_position from public.players p),
windows as (
  select a.*, g.number as start_number, e.number as end_number
  from public.player_team_assignments a join season s on s.id = a.season_id
  left join public.gameweeks g on g.id = a.starts_gameweek_id and g.season_id = a.season_id
  left join public.gameweeks e on e.id = a.ends_gameweek_id and e.season_id = a.season_id
), eligibility as (
  select p.*, exists(select 1 from public.fixtures f join season s on s.id = f.season_id
    where p.team_id in (f.home_team_id, f.away_team_id)) as current_team,
    exists(select 1 from windows w join public.fixtures f on f.season_id = w.season_id
      and w.team_id in (f.home_team_id, f.away_team_id)
      join public.gameweeks g on g.id = f.gameweek_id and g.season_id = f.season_id
      where w.player_id = p.id and w.start_number <= g.number
        and (w.ends_gameweek_id is null or w.end_number >= g.number)) as has_history
  from ranked p
), identity_groups as (
  select a.source_key, count(distinct a.player_id) as rows,
    array_agg(distinct a.player_id) as player_ids
  from public.player_name_aliases a group by a.source_key having count(distinct a.player_id) > 1
), name_groups as (
  select public.pp_player_identity_key(p.display_name) as key, array_agg(p.id) as player_ids
  from public.players p group by 1 having count(*) > 1
)
select 'active_beyond_api_cap', p.id, p.display_name,
  jsonb_build_object('row_number', p.api_position, 'cap', api_row_cap, 'team_id', p.team_id)
from eligibility p where p.is_active and (p.current_team or p.has_history) and p.api_position > api_row_cap
union all
select 'active_missing_eligible_history', p.id, p.display_name, jsonb_build_object('team_id', p.team_id)
from eligibility p where p.is_active and p.current_team and not p.has_history
union all
select 'active_outside_season_pool', p.id, p.display_name, jsonb_build_object('team_id', p.team_id)
from eligibility p where p.is_active and not p.current_team and not p.has_history
union all
select 'deactivated_with_history_review_only', p.id, p.display_name, jsonb_build_object('team_id', p.team_id)
from eligibility p where not p.is_active and p.has_history
union all
select 'documented_duplicate_identity_review', p.id, p.display_name,
  jsonb_build_object('source', g.source_key, 'related_player_ids', g.player_ids, 'is_active', p.is_active)
from identity_groups g join public.players p on p.id = any(g.player_ids)
union all
select 'duplicate_name_review', p.id, p.display_name,
  jsonb_build_object('related_player_ids', g.player_ids, 'is_active', p.is_active, 'team_id', p.team_id)
from name_groups g join public.players p on p.id = any(g.player_ids)
union all
select 'invalid_assignment_window', p.id, p.display_name, to_jsonb(w)
from windows w join public.players p on p.id = w.player_id
where w.start_number is null or (w.ends_gameweek_id is not null and (w.end_number is null or w.end_number < w.start_number))
union all
select 'assignment_to_nonseason_club', p.id, p.display_name, to_jsonb(w)
from windows w join public.players p on p.id = w.player_id
where not exists (select 1 from public.fixtures f where f.season_id = w.season_id and w.team_id in (f.home_team_id, f.away_team_id))
union all
select 'overlapping_club_assignments', p.id, p.display_name,
  jsonb_build_object('assignment_a', a.id, 'assignment_b', b.id)
from windows a join windows b on a.player_id = b.player_id and a.id < b.id and a.team_id <> b.team_id
  and a.start_number <= coalesce(b.end_number, 2147483647) and b.start_number <= coalesce(a.end_number, 2147483647)
join public.players p on p.id = a.player_id
union all
select 'current_team_open_assignment_mismatch_review', p.id, p.display_name,
  jsonb_build_object('current_team_id', p.team_id, 'assignment', to_jsonb(w))
from windows w join public.players p on p.id = w.player_id
where p.is_active and w.ends_gameweek_id is null and p.team_id is distinct from w.team_id
union all
select 'fixture_stat_without_matching_history', p.id, p.display_name,
  jsonb_build_object('fixture_id', x.fixture_id, 'gameweek_id', x.gameweek_id, 'team_id', x.team_id)
from public.player_fixture_stats x join season s on s.id = x.season_id
join public.players p on p.id = x.player_id
join public.gameweeks gw on gw.id = x.gameweek_id and gw.season_id = x.season_id
where not exists (select 1 from windows w where w.player_id = x.player_id and w.team_id = x.team_id
  and w.start_number <= gw.number and (w.ends_gameweek_id is null or w.end_number >= gw.number));
$$;
revoke all on function public.audit_player_stats_pool(integer) from public;
grant execute on function public.audit_player_stats_pool(integer) to authenticated;

-- Keep the report in a block variable; emit it as a SQL Editor notice after cleanup.
select jsonb_build_object(
  'repairs', coalesce((select jsonb_agg(to_jsonb(r) order by repair, display_name)
    from public.pp_migration_player_stats_20260829_repairs r), '[]'::jsonb),
  'review', coalesce((select jsonb_agg(to_jsonb(a) order by issue, display_name) from public.audit_player_stats_pool() a), '[]'::jsonb)
) into player_stats_integrity_report;
drop table
  public.pp_migration_player_stats_20260829_unique_active,
  public.pp_migration_player_stats_20260829_identity_matches,
  public.pp_migration_player_stats_20260829_identity_source,
  public.pp_migration_player_stats_20260829_repairs,
  public.pp_migration_player_stats_20260829_season;
raise notice 'player_stats_integrity_report: %', player_stats_integrity_report;
end
$player_stats_migration$;

-- Subsequent audit (no writes):
-- select * from public.audit_player_stats_pool() order by issue, display_name;
-- Never treat the review report as a list of players to reactivate or delete.
